import * as React from "react";

export interface IconProps {
  /** Square icon dimension in pixels. */
  size?: number;
  className?: string;
}

export interface NavIconProps extends IconProps {
  /** Renders the filled Zappicon state when active and the Regular outline state when inactive. */
  active?: boolean;
}

interface IconSvgProps extends IconProps {
  viewBox: string;
  children: React.ReactNode;
}

function IconSvg({ size = 24, viewBox, className = "", children }: IconSvgProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      className={`shrink-0 ${className}`.trim()}
    >
      {children}
    </svg>
  );
}

